script:
(function () {
  'use strict';
  // 403(b) with no employer money: your own deferrals only, with the 403(b) 15-year catch-up and the
  // cost of fees. Deposits go in monthly. Each month the balance grows at the monthly equivalent of the
  // gross return, (1 + r)^(1/12) - 1, and the percentage fee takes the gap between that and the monthly
  // equivalent of (return - fee), the same net-of-fee convention as 403b-savings-calculator; a flat
  // account fee is taken in 12 equal parts. The same projection is re-run at the lower comparison fee and
  // (when chosen) without the 15-year rule to show what each is worth at retirement.
  // Deferral limit each year = basic 402(g) limit + 15-year catch-up + age catch-up, and never more than
  // pay. 15-year rule (Pub. 571 ch. 4, Worksheet 1): with 15+ years of service for a qualifying employer,
  // the limit rises by the least of $3,000; $15,000 minus 15-year increases used before; or $5,000 x
  // years of service minus all elective deferrals to that employer in earlier years. Deferrals above the
  // basic limit count first as 15-year catch-up, then as age 50+ catch-up.
  // Checked in Node (scratchpad solo401k/tests/nm.test.js): $6,000/yr, no fee, 30 years at 7% =
  // $584,726 (annuity formula with the monthly-equivalent rate, as 403b-savings-calculator); 1% fee at
  // 7% = the 6% no-fee value ($487,256); limits $24,500 (age 40), $32,500 (55), $35,750 (61); 15 years of
  // service with $60,000 earlier deferrals -> +$3,000 = $27,500; $73,000 -> +$2,000; $14,000 used -> +$1,000;
  // 20 years and no earlier deferrals -> five years at +$3,000 then the $15,000 lifetime cap.
  // ---- 2026 IRS limits (IRS Notice 2025-67; Pub. 571, Rev. January 2026) -----------------------------
  var LIMITS = {
    year: 2026,
    deferral: 24500,        // 402(g) elective deferral limit (pre-tax + Roth)
    catchUp50: 8000,        // 414(v) catch-up, age 50 or older by year-end
    catchUp60to63: 11250,   // SECURE 2.0 higher catch-up, ages 60-63 (instead of the age-50 amount)
    service: { yearly: 3000, lifetime: 15000, perYear: 5000, minYears: 15 } // 15-year rule (not indexed)
  };
  // ----------------------------------------------------------------------------------------------------

  function catchUpFor(age) {
    if (age >= 60 && age <= 63) return LIMITS.catchUp60to63;
    if (age >= 50) return LIMITS.catchUp50;
    return 0;
  }
  function serviceCatchUp(yos, used, priorDeferrals) {
    if (yos < LIMITS.service.minYears) return 0;
    return Math.max(0, Math.min(LIMITS.service.yearly, LIMITS.service.lifetime - used,
                                LIMITS.service.perYear * yos - priorDeferrals));
  }

  // p: age, retireAge, salary, raise, balance, mode ('pct'|'dollar'|'max'), pct, dollar, rate, fee, flat,
  //    inflation (decimals), service (bool), yos, prior, used.
  function project(p) {
    var years = p.retireAge - p.age;
    var mGross = Math.pow(1 + p.rate, 1 / 12) - 1, mNet = Math.pow(Math.max(0, 1 + p.rate - p.fee), 1 / 12) - 1;
    var bal = p.balance, salary = p.salary, used = p.used, prior = p.prior, totYou = 0, totFees = 0;
    var rows = [], capped = false, first = null;
    for (var y = 0; y < years; y++) {
      var ageNow = p.age + y;
      var extra = p.service ? serviceCatchUp(p.yos + y, used, prior) : 0;
      var ageCatch = catchUpFor(ageNow);
      var limit = Math.min(LIMITS.deferral + extra + ageCatch, salary);
      var want = p.mode === 'max' ? limit : p.mode === 'dollar' ? p.dollar : salary * p.pct;
      var you = Math.min(want, limit);
      if (want > limit + 0.005 && p.mode !== 'max') capped = true;
      var fromService = Math.min(Math.max(0, you - LIMITS.deferral), extra);
      used += fromService; prior += you;
      if (y === 0) first = { extra: extra, ageCatch: ageCatch, limit: LIMITS.deferral + extra + ageCatch, salary: salary };
      var dep = you / 12, fees = 0;
      for (var m = 0; m < 12; m++) {
        var pctFee = bal * (mGross - mNet), flat = Math.min(p.flat / 12, bal * (1 + mNet));
        bal = bal * (1 + mNet) - flat + dep;
        fees += pctFee + flat;
      }
      totYou += you; totFees += fees;
      rows.push({ age: ageNow, salary: salary, you: you, fromService: fromService, fees: fees, balance: bal });
      salary = salary * (1 + p.raise);
    }
    return { balance: bal, real: bal / Math.pow(1 + p.inflation, years), you: totYou, fees: totFees, rows: rows,
             capped: capped, first: first };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return moneyFmt.format(Math.abs(x) < 0.5 ? 0 : x); }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, t) { document.getElementById(id).textContent = t; }

  function update() {
    var mode = document.getElementById('nmMode').value, service = document.getElementById('nmService').checked;
    document.getElementById('nmPctWrap').hidden = mode !== 'pct';
    document.getElementById('nmDollarWrap').hidden = mode !== 'dollar';
    document.getElementById('nmServiceFields').hidden = !service;
    var p = { age: num('nmAge'), retireAge: num('nmRetireAge'), salary: num('nmSalary'), raise: num('nmRaise'),
              balance: num('nmBalance'), mode: mode, pct: num('nmPct'), dollar: num('nmDollar'), rate: num('nmRate'),
              fee: num('nmFee'), lowFee: num('nmLowFee'), flat: num('nmFlat'), inflation: num('nmInflation'),
              service: service, yos: num('nmYos'), prior: num('nmPrior'), used: num('nmUsed') };
    if (mode !== 'pct') p.pct = 0;
    if (mode !== 'dollar') p.dollar = 0;
    if (!service) { p.yos = 0; p.prior = 0; p.used = 0; }
    var error = document.getElementById('nmError');
    var bad = [p.age, p.retireAge, p.salary, p.raise, p.balance, p.pct, p.dollar, p.rate, p.fee, p.lowFee, p.flat,
               p.inflation, p.yos, p.prior, p.used].some(isNaN) ||
              p.age !== Math.round(p.age) || p.retireAge !== Math.round(p.retireAge) || p.age < 16 || p.age > 99 ||
              p.retireAge <= p.age || p.retireAge > 100 || p.salary < 0 || p.balance < 0 || p.raise < 0 || p.raise > 20 ||
              p.pct < 0 || p.pct > 100 || p.dollar < 0 || p.rate < 0 || p.rate > 30 || p.fee < 0 || p.fee > 5 ||
              p.lowFee < 0 || p.lowFee > 5 || p.flat < 0 || p.flat > 1000 || p.inflation < 0 || p.inflation > 20 ||
              p.yos < 0 || p.yos > 60 || p.prior < 0 || p.used < 0 || p.used > 15000;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter whole-number ages from 16 to 99 with retirement above your age (up to 100), non-negative amounts, ' +
                          'a contribution up to 100% of pay, a return up to 30%, fees up to 5%, a flat fee up to $1,000, ' +
                          'inflation up to 20%, 0 to 60 years of service and up to $15,000 of 15-year catch-up already used.';
      return;
    }
    ['raise', 'pct', 'rate', 'fee', 'lowFee', 'inflation'].forEach(function (k) { p[k] = p[k] / 100; });
    p.yos = Math.floor(p.yos);
    var r = project(p);
    var low = project(Object.assign({}, p, { fee: p.lowFee }));
    var noService = service ? project(Object.assign({}, p, { service: false })) : r;
    set('nmRetireLabel', 'Balance at age ' + p.retireAge);
    set('nmFuture', fmt(r.balance)); set('nmReal', fmt(r.real)); set('nmYou', fmt(r.you)); set('nmFeesPaid', fmt(r.fees));
    set('nmLowLabel', 'At a ' + (Math.round(p.lowFee * 10000) / 100) + '% fee instead');
    set('nmLowBal', fmt(low.balance));
    var svcGain = r.balance - noService.balance;
    set('nmServiceGain', !service ? 'Not used' : svcGain > 0.5 ? fmt(svcGain) : 'None at this contribution');
    var gap = low.balance - r.balance;
    set('nmFeeGap', gap > 0.5
      ? 'Your fees cost you ' + fmt(gap) + ' by age ' + p.retireAge + ' compared with the lower-cost option, ' +
        Math.round(gap / low.balance * 100) + '% of what you could have had.'
      : gap < -0.5 ? 'The comparison fee is higher than your plan’s, so your plan comes out ' + fmt(-gap) + ' ahead.'
      : 'Your fee and the comparison fee are the same.');
    var capEl = document.getElementById('nmCapped');
    capEl.hidden = !r.capped;
    if (r.capped) set('nmCapped', 'In some years your contribution is reduced to your ' + LIMITS.year + ' IRS limit or to your pay.');
    var f = r.first;
    set('nmLimBasic', fmt(LIMITS.deferral)); set('nmLimService', service ? fmt(f.extra) : 'Not used');
    set('nmLimAge', fmt(f.ageCatch)); set('nmLimTotal', fmt(f.limit));
    set('nmLimPct', f.salary > 0 ? (f.limit > f.salary ? 'More than your pay' : (Math.ceil(f.limit / f.salary * 1000) / 10) + '%') : '–');
    var body = document.getElementById('nmSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, fmt(row.salary), fmt(row.you), fmt(row.fromService), fmt(row.fees), fmt(row.balance)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('nmForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
